head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil30801";
scwin.chkReservPosbl = "";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_nowVars
 * @description 현재 시각 파생값 충전 — as-is JSP 계산분(서버 데이터 아님)
 * @returns {void}
 * @hidden N
 */
scwin.init_nowVars = function () {
    const pc = $c.util.getComponent('dma_pageContext');
    if (!pc || !pc.set || !pc.get) { return; }
    if (!pc.get("today")) { pc.set("today", $c.date.getServerDateTime("yyyyMMdd")); }
};

/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "__rb0", attr: "label", fn: function () { return String(String((dma_pageContext.get("comNm") ?? ""))); } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        let v;
        try { v = a.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId }); return; }
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "cal_applDd", fn: function () { return String((dma_pageContext.get("calDd") ?? "")); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

// 세션 사용자 결선 (어휘 session_attribute 1건 — gcc $c.session.getUserInfo)

/**
 * @method
 * @name init_sessionFill
 * @description 초기화 — session Fill
 * @returns {void}
 * @hidden N
 */
scwin.init_sessionFill = function () {
    const names = ["isurCd"];
    function fill() {
        for (let i = 0; i < names.length; i++) {
            let v; try { v = $c.session.getUserInfo(names[i]); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil30801' }); v = undefined; }
            if (v === undefined || v === null || v === '') { continue; }
            const token = '${session.user.' + names[i] + '}';
            let r0 = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document); r0 = r0.body || r0; const doc = r0.ownerDocument || r0; const w = doc.createTreeWalker(r0, NodeFilter.SHOW_TEXT);
            let n; while ((n = w.nextNode())) { if (n.nodeValue.indexOf(token) >= 0) { n.nodeValue = n.nodeValue.split(token).join(v); } }
            const ins = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelectorAll('input, textarea');
            for (let j = 0; j < ins.length; j++) { if (ins[j].value && ins[j].value.indexOf(token) >= 0) { ins[j].value = ins[j].value.split(token).join(v); } }
        }
    }
    fill();
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: entry_edge). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_load_list();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.form_iRScheduleForm = { action: "", method: 'post', target: '' };

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_nowVars();
        scwin.init_rowCopy();
        scwin.init_attrReals();
        scwin.init_sessionFill();
        await scwin.init_loadList();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil30801.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name slc_confroomTpCd_onchange
 * @description slc_confroomTpCd 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.slc_confroomTpCd_onchange = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        scwin.changeState(selfVar)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil30801.slc_confroomTpCd_onchange' }); }
};

/**
 * @method
 * @name slc_irTpCd_onchange
 * @description slc_irTpCd 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.slc_irTpCd_onchange = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        scwin.changeIRTp(selfVar)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil30801.slc_irTpCd_onchange' }); }
};

/**
 * @method
 * @name cal_applDd_onblur
 * @description cal_applDd 포커스 이탈 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cal_applDd_onblur = async function(e){
    try {
        await (async (c) => { const raw = String((c && c.getValue) ? (c.getValue() ?? "") : ""); if (raw.length === 0) { return true; } const v = raw.split("-").join("").split("/").join(""); if (c && c.setValue) { c.setValue(v); } const lbl = ""; const lp = lbl ? (lbl + ": ") : ""; if (v.length !== 8) { await $c.win.alert(lp + "날짜는 8 자리 YYYYMMDD 형식입니다."); if (c && c.focus) { c.focus(); } return false; } let digits = true; for (let i = 0; i < v.length; i++) { const ch = v.charAt(i); if (ch < "0" || ch > "9") { digits = false; break; } } if (!digits) { await $c.win.alert(lp + "숫자만 입력가능합니다."); if (c && c.focus) { c.focus(); } return false; } const mm = Number(v.substring(4, 6)); if (mm > 12 || mm < 1) { await $c.win.alert(lp + "달은 1 에서 12 사이여야 합니다."); if (c && c.focus) { c.focus(); } return false; } if (!$c.date.checkCalendarFormat(c, "yyyyMMdd", { clearOnInvalid: false })) { await $c.win.alert(lp + " 존재하지 않는 날짜입니다."); if (c && c.focus) { c.focus(); } return false; } return true; })($c.util.getComponent("cal_applDd"));

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil30801.cal_applDd_onblur' }); }
};

/**
 * @method
 * @name btn_register_onclick
 * @description 「임시저장」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_register_onclick = async function(e){
    try {
        await scwin.register()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil30801.btn_register_onclick' }); }
};

/**
 * @method
 * @name btn_application_onclick
 * @description 「신청」 클릭 이벤트
