};

/**
 * @method
 * @name btn_cancle_onclick
 * @description 「신청취소」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_cancle_onclick = async function(e){
    try {
        await scwin.cancle()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil30801.btn_cancle_onclick' }); }
};

/**
 * @method
 * @name grd_calendarWeekList_oncellclick
 * @description grd_calendarWeekList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_calendarWeekList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_calendarWeekList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_calendarWeekList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; } /* 수동 전환 필요: fn_dataSet('${schedule.applNo}','${schedule.confroomTpCd}', '${schedule.irTpCd}', '${schedule.calndDd}', '${fn:substring(schedule.useStrtDdtm, 8, 10)}', '${fn:substring(schedule.useEndDdtm, 8, 10)}', '${schedule.acptNm}', '${schedule.acptEmail}', '${schedule.reservStatTpCd}'); (EL 미해석) */
        await scwin.schedules2(r["code"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_calendarWeekList.oncellclick' });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_findSchedules
 * @description find Schedules 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_findSchedules = async function () {
    const sbmOptions = {
        id: "tx_fn_findSchedules",
        method: "post",
        action: "/issue/IRSupport.do",
        ref: "dma_findSchedulesReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

