        id: "tx_load_list",
        method: "post",
        action: "/issue/IRSupport.do?method=searchIRSupportInfo",
        ref: "dma_loadListReq",
        target: "dlt_calendarWeekList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name list
 * @description list 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.list = async function () {
    $c.util.getComponent('listTab').src = "/img/main/calendar_tab_1_selected.gif";
    $c.util.getComponent('calTab').src = "/img/main/calendar_tab_2.gif";
    $c.util.getComponent('dma_findSchedulesReq').set('displayDiv', "list");
    await scwin.findSchedules();
};

/**
 * @method
 * @name calendar
 * @description calendar 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.calendar = async function () {
    $c.util.getComponent('listTab').src = "/img/main/calendar_tab_1.gif";
    $c.util.getComponent('calTab').src = "/img/main/calendar_tab_2_selected.gif";
    $c.util.getComponent('dma_findSchedulesReq').set('displayDiv', "calendar");
    await scwin.findSchedules();
};

/**
 * @method
 * @name schedules1
 * @description schedules1 처리
 * @param {*} year year
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.schedules1 = async function (year) {
    await scwin.findSchedules();
};

/**
 * @method
 * @name schedules2
 * @description schedules2 처리
 * @param {*} month month
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.schedules2 = async function (month) {
    document.all["span" + $c.util.getComponent('dma_findSchedulesReq').get('month')].className = "";
    document.all["span" + month].className = "thisMonth";
    $c.util.getComponent('dma_findSchedulesReq').set('month', month);
    await scwin.findSchedules();
};

/**
 * @method
 * @name findSchedules
 * @description find Schedules 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.findSchedules = async function () {
    scwin.form_iRScheduleForm.action = "/issue/IRSupport.do";
    $c.util.getComponent('dma_findSchedulesReq').set('method', "searchIRSupportAppl");
    const nr = await scwin.tx_fn_findSchedules();
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/jldfil30800/jldfil30800.xml", { "method": "searchIRSupportAppl" });
    }
};

/**
 * @method
 * @name changeIRTp
 * @description change IRTp 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.changeIRTp = function (obj) {
    const irTp = obj.value;
    if (irTp != null && irTp === "1") {
        $c.util.getComponent("slc_confroomTpCd").setValue("0030");
        document.iRScheduleForm.confroomTpCd[0].selected = true;
    } else {
        if (irTp != null && irTp === "2") {
            $c.util.getComponent("slc_confroomTpCd").setValue("0030");
            document.iRScheduleForm.confroomTpCd[0].selected = true;
        }
    }
};

/**
 * @method
 * @name changeState
 * @description change State 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.changeState = function (obj) {
    const cRoom = obj.value;
    if (cRoom === "0012") {
        $c.util.getComponent("slc_irTpCd").setValue("3");
        document.iRScheduleForm.irTpCd[2].selected = true;
    }
};

/**
 * @method
 * @name register
 * @description register 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.register = async function () {
    if (($c.util.getComponent('cal_applDd').getValue() == null ? '' : String($c.util.getComponent('cal_applDd').getValue())) === '') {
        await $c.win.alert("『이용 가능 서비스 안내』메뉴에서 가능한 날짜를 선택하여 신청서를 작성해주세요.");
        return;
    }
    if (await $c.fil.checkRequired($c.util.getComponent('ipt_acptNm'))) {
        return;
    }
    if (await $c.fil.checkRequired($c.util.getComponent('ipt_acptEmail'))) {
        return;
    }
    if ($c.util.getComponent('dma_findSchedulesReq').get('statTpCd') === '3') {
        await $c.win.alert("승인된 신청 건은 수정할 수 없습니다.");
        return;
    }
    scwin.form_iRScheduleForm.action = "/issue/IRSupport.do";
    $c.util.getComponent('dma_findSchedulesReq').set('method', "registIRSupportAppl");
    $c.util.getComponent('dma_findSchedulesReq').set('useStrtDdtm', $c.util.getComponent('cal_applDd').getValue()+ $c.util.getComponent('slc_time1').getValue()+ "");
    $c.util.getComponent('dma_findSchedulesReq').set('useEndDdtm', $c.util.getComponent('cal_applDd').getValue()+ $c.util.getComponent('slc_time2').getValue()+ "");
    const nr = await scwin.tx_fn_register();
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/jldfil30800/jldfil30800.xml", { "method": "registIRSupportAppl" });
    }
};

/**
 * @method
 * @name application
 * @description application 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.application = async function () {
    if (($c.util.getComponent('cal_applDd').getValue() == null ? '' : String($c.util.getComponent('cal_applDd').getValue())) === '') {
        await $c.win.alert("『이용 가능 서비스 안내』메뉴에서 가능한 날짜를 선택하여 신청서를 작성해주세요.");
        return;
    } else {
        await scwin.checkIsPosbl($c.util.getComponent('cal_applDd').getValue(), $c.util.getComponent('slc_irTpCd').getValue(), $c.util.getComponent('slc_confroomTpCd').getValue());
        if (today > $c.util.getComponent('cal_applDd').getValue()) {
            await $c.win.alert("오늘 이전 일자로 예약은 불가능합니다.");
            return;
        }
        if (scwin.chkReservPosbl === 'N') {
            await $c.win.alert("예약 가능한 일자가 아닙니다. 다른 일자를 선택하세요. : " + $c.util.getComponent('cal_applDd').getValue());
            return;
        }
    }
    if (await $c.fil.checkRequired($c.util.getComponent('ipt_acptNm'))) {
        return;
    }
    if (await $c.fil.checkRequired($c.util.getComponent('ipt_acptEmail'))) {
        return;
    }
    if ($c.util.getComponent('dma_findSchedulesReq').get('statTpCd') === '3') {
        await $c.win.alert("승인된 신청 건은 수정할 수 없습니다.");
        return;
    }
    $c.util.getComponent('dma_findSchedulesReq').set('useStrtDdtm', $c.util.getComponent('cal_applDd').getValue()+ $c.util.getComponent('slc_time1').getValue()+ "");
    $c.util.getComponent('dma_findSchedulesReq').set('useEndDdtm', $c.util.getComponent('cal_applDd').getValue()+ $c.util.getComponent('slc_time2').getValue()+ "");
    scwin.form_iRScheduleForm.action = "/issue/IRSupport.do";
    $c.util.getComponent('dma_findSchedulesReq').set('method', "submitIRSupportAppl");
    const nr = await scwin.tx_fn_application();
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/jldfil30800/jldfil30800.xml", { "method": "submitIRSupportAppl" });
    }
};

/**
 * @method
 * @name cancle
 * @description cancle 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cancle = async function () {
    if ($c.util.getComponent('dma_findSchedulesReq').get('statTpCd') === '3') {
        await $c.win.alert("승인된 신청 건은 취소할 수 없습니다.");
        return;
    } else {
        if ($c.util.getComponent('dma_findSchedulesReq').get('statTpCd') === '4') {
            await $c.win.alert("이미 취소된 신청 건입니다.");
            return;
        } else {
            if (await $c.win.confirm("선택하신 신청내역을 취소하시겠습니까?")) {
                scwin.form_iRScheduleForm.action = "/issue/IRSupport.do";
                $c.util.getComponent('dma_findSchedulesReq').set('method', "cancleIRSupportAppl");
                const nr = await scwin.tx_fn_cancle();
                if (nr && nr.responseJSON && nr.responseJSON.success === true) {
                    $c.win.moveUrl("/jldfil30800/jldfil30800.xml", { "method": "cancleIRSupportAppl" });
                }
            } else {
                return;
            }
        }
    }
};

/**
 * @method
 * @name dataSet
 * @description data Set 처리
 * @param {*} applNo applNo
 * @param {String} confroomTpCd confroomTpCd
 * @param {String} irTpCd irTpCd
 * @param {String} applDd applDd
 * @param {*} strtTm strtTm
 * @param {*} endTm endTm
 * @param {String} acptNm acptNm
 * @param {*} acptEmail acptEmail
 * @param {String} statTpCd statTpCd
 * @returns {void}
 * @hidden N
 */
scwin.dataSet = function (applNo, confroomTpCd, irTpCd, applDd, strtTm, endTm, acptNm, acptEmail, statTpCd) {
    $c.util.getComponent('dma_findSchedulesReq').set('applNo', applNo);
    (($c.util.getComponent('slc_confroomTpCd'))?.setValue?.(confroomTpCd));
    (($c.util.getComponent('slc_irTpCd'))?.setValue?.(irTpCd));
    $c.util.getComponent("cal_applDd").setValue(applDd);
    (($c.util.getComponent('slc_time1'))?.setValue?.(strtTm));
    (($c.util.getComponent('slc_time2'))?.setValue?.(endTm));
    $c.util.getComponent("ipt_acptNm").setValue(acptNm);
    $c.util.getComponent("ipt_acptEmail").setValue(acptEmail);
    $c.util.getComponent('dma_findSchedulesReq').set('statTpCd', statTpCd);
    if (statTpCd === '1') {
        $c.util.getComponent("btn_Save").hide();
        $c.util.getComponent("btn_Apply").show();
        $c.util.getComponent("btn_Cancle").show();
    } else {
        if (statTpCd === '0' || statTpCd === '2') {
            $c.util.getComponent("btn_Save").show();
            $c.util.getComponent("btn_Apply").show();
            $c.util.getComponent("btn_Cancle").hide();
        } else {
            if (statTpCd === '3') {
                $c.util.getComponent("btn_Save").hide();
                $c.util.getComponent("btn_Apply").hide();
                $c.util.getComponent("btn_Cancle").show();
            } else {
                if (statTpCd === '4') {
                    $c.util.getComponent("btn_Save").hide();
                    $c.util.getComponent("btn_Apply").hide();
                    $c.util.getComponent("btn_Cancle").hide();
                }
            }
        }
    }
    if (today > applDd) {
        $c.util.getComponent("btn_Save").hide();
        $c.util.getComponent("btn_Apply").hide();
        $c.util.getComponent("btn_Cancle").hide();
    }
};

/**
 * @method
 * @name selectboxChk
 * @description selectbox Chk 처리
 * @param {*} _obj _obj
 * @param {*} chkVal chkVal
 * @returns {void}
 * @hidden N
 */
scwin.selectboxChk = function (_obj, chkVal) {
    for (let i = 0; i < _obj.getItemCount(); i++) {
        if (_obj[i].value === chkVal) {
            _obj[i].selected = true;
        }
    }
};

// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)

/**
 * @method
 * @name checkIsPosbl_done
 * @description check Is Posbl done 처리
 * @param {*} data 데이터
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkIsPosbl_done = async function (data) {
    try {
        const result = (typeof data === "string" ? JSON.parse(data) : data);
        scwin.chkReservPosbl = result.chkReservPosbl;
    } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'jldfil30801' });
        await $c.win.alert("예약가능여부 조회에 실패하였습니다. 관리자에게 문의하십시오.");
    }
};

/**
 * @method
 * @name checkIsPosbl
 * @description check Is Posbl 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkIsPosbl = async function () {
    const r = await scwin.tx_checkIsPosbl();
    try {
        scwin.checkIsPosbl_done.call(window, JSON.stringify((r && r.responseJSON && (r.responseJSON.body != null ? r.responseJSON.body : r.responseJSON)) || {}));
    }
    catch (_se) {
        await $c.exception.handleError(_se, { notify: 'none', context: 'jldfil30801.checkIsPosbl' });
    }
    return r;
};
